#include <stddef.h>
#include <stdint.h>
#include <microkit.h>
#include <serial_config.h>
#include <libvmm/util/atomic.h>
#include <libvmm/util/queue.h>
#include <sddf/sound/queue.h>
#include <sddf/util/printf.h>

#define BUFFER_QUEUE_SIZE SOUND_PCM_QUEUE_SIZE
#define PREFILL_BUFFERS 5

#define SERIAL_TX_CH 0
#define SERIAL_RX_CH 1
#define BENCH_START_CH 2
#define BENCH_STOP_CH 3
#define VIRT_CH 4

serial_queue_t *serial_tx_queue;
serial_queue_t *serial_rx_queue;

char *serial_tx_data;
char *serial_rx_data;

serial_queue_handle_t tx_queue_handle;
serial_queue_handle_t rx_queue_handle;

struct audio {
    unsigned format;
    unsigned channels;
    unsigned frame_size;
    unsigned rate;

    const unsigned char *data;
    unsigned len;
} audio;

static const unsigned char CantinaBand60_s16le[];
static const unsigned char crab_rave_pcm_s16le[];

#define CRAB
// #define CANTINA

typedef enum stream_state {
    STATE_INIT,
    STATE_RESET,
    STATE_TAKEN,
    STATE_PREPARED,
    STATE_STARTED,
    STATE_DRAINING,
    STATE_ERR,
} stream_state_t;

uintptr_t sound_cmd_req;
uintptr_t sound_cmd_res;
uintptr_t sound_pcm_req;
uintptr_t sound_pcm_res;

uintptr_t sound_data_region;
uintptr_t sound_shared_state;

static sound_shared_state_t *shared_state;
static sound_queues_t queues;
static stream_state_t stream_state;

static int playback_stream;
static uint32_t curr_cookie = 1;

static long buffer_offset;

static queue_t free_buffers;
static uintptr_t buffer_data[BUFFER_QUEUE_SIZE];

static void fail(void) {
    sddf_printf("Stream in fail state\n");
    stream_state = STATE_ERR;
}

static unsigned int min(unsigned int a, unsigned int b) {
    return a < b ? a : b;
}

static bool stream_supported(sound_pcm_info_t *info) {
    return
        (info->direction == SOUND_D_OUTPUT) &&
        (info->formats & (audio.format)) &&
        (info->rates   & (audio.rate));
}

static void notified_init(void) {

    // Find first playback stream
    playback_stream = -1;
    for (int i = 0; i < shared_state->streams; i++) {
        if (stream_supported(&shared_state->stream_info[i])) {
            playback_stream = i;
            break;
        }
    }
    if (playback_stream == -1) {
        sddf_printf("Failed to find compatible stream\n");
        fail();
        return;
    }

    sound_cmd_t cmd;
    cmd.code = SOUND_CMD_TAKE;
    cmd.cookie = curr_cookie++;
    cmd.stream_id = playback_stream;
    cmd.set_params.channels = audio.channels;
    cmd.set_params.format = audio.format;
    cmd.set_params.rate = audio.rate;

    sddf_printf("Taking stream %d\n", playback_stream);
    int err = sound_enqueue_cmd(&queues.cmd_req, &cmd);
    if (err) {
        sddf_printf("Failed to enqueue command\n");
        fail();
        return;
    }

    stream_state = STATE_RESET;
    microkit_notify(VIRT_CH);
}

static bool send_simple_command(sound_cmd_code_t code) {
    sound_cmd_t cmd;
    cmd.code = code;
    cmd.cookie = curr_cookie++;
    cmd.stream_id = playback_stream;

    int err = sound_enqueue_cmd(&queues.cmd_req, &cmd);
    if (err) {
        sddf_printf("Failed to enqueue command\n");
        return false;
    }
    return true;
}

static bool expect_response(sound_cmd_code_t code) {
    sound_cmd_t cmd;
    int err = sound_dequeue_cmd(&queues.cmd_res, &cmd);
    if (err) {
        sddf_printf("Expected response but didn't get one\n");
        return false;
    }
    if (cmd.code != code) {
        sddf_printf("Expected command code %s but got %s\n",
                sound_command_code_str(code),
                sound_command_code_str(cmd.code));
        return false;
    }
    if (cmd.status != SOUND_S_OK) {
        sddf_printf("Failed to %s: %s\n",
                sound_command_code_str(code),
                sound_status_code_str(cmd.status));
        return false;
    }
    return true;
}

static void notified_reset(void) {

    if (!expect_response(SOUND_CMD_TAKE)) {
        fail();
        return;
    }

    sddf_printf("Preparing stream\n");
    if (!send_simple_command(SOUND_CMD_PREPARE)) {
        fail();
        return;
    }

    stream_state = STATE_TAKEN;
    microkit_notify(VIRT_CH);
}

static bool send_pcm(uintptr_t buf_offset, const void *data, unsigned int len) {

    sound_pcm_t pcm;

    len = min(len, SOUND_PCM_BUFFER_SIZE);

    pcm.cookie = curr_cookie++;
    pcm.stream_id = playback_stream;
    pcm.io_or_offset = buf_offset;
    pcm.len = len;
    pcm.status = SOUND_S_OK;
    pcm.latency_bytes = 0;

    void *pcm_buffer = (void *)sound_data_region + buf_offset;
    memcpy(pcm_buffer, data, len);

    if (sound_enqueue_pcm(&queues.pcm_req, &pcm) != 0) {
        sddf_printf("Failed to enqueue PCM\n");
        return false;
    }

    return true;
}

static void notified_taken(void) {

    if (!expect_response(SOUND_CMD_PREPARE)) {
        fail();
        return;
    }

    // Prefill
    sddf_printf("Sending %d prefill buffers\n", PREFILL_BUFFERS);
    for (int i = 0; i < PREFILL_BUFFERS; i++) {
        unsigned int offset = i * SOUND_PCM_BUFFER_SIZE;
        if (offset >= audio.len) {
            break;
        }

        unsigned int buf_len = min(audio.len - offset, SOUND_PCM_BUFFER_SIZE);

        uintptr_t buf_offset;
        if (queue_dequeue_front(&free_buffers, &buf_offset) == false) {
            sddf_printf("No free buffers available\n");
            fail();
            return;
        }


        if (!send_pcm(buf_offset, &audio.data[offset], buf_len)) {
            fail();
            return;
        }
    }

    sddf_printf("Starting stream\n");
    if (!send_simple_command(SOUND_CMD_START)) {
        fail();
        return;
    }

    stream_state = STATE_PREPARED;
    microkit_notify(VIRT_CH);
}

static void update_playback(void) {

    bool notify = false;
    sound_pcm_t pcm;
    while (sound_dequeue_pcm(&queues.pcm_res, &pcm) == 0) {

        if (buffer_offset >= audio.len) {
            break;
        }

        unsigned int buf_len = min(audio.len - buffer_offset, SOUND_PCM_BUFFER_SIZE);

        if (!send_pcm(pcm.io_or_offset, &audio.data[buffer_offset], buf_len)) {
            fail();
            return;
        }
        buffer_offset += buf_len;

        notify = true;
    }

    if (buffer_offset >= audio.len) {
        sddf_printf("Stopping stream\n");
        if (!send_simple_command(SOUND_CMD_STOP)) {
            fail();
            return;
        }
        notify = true;
        stream_state = STATE_DRAINING;

        // Stop benchmark
        microkit_notify(BENCH_STOP_CH);
    }

    if (notify) {
        microkit_notify(VIRT_CH);
    }
}

static void notified_prepared(void) {

    sound_cmd_t cmd;
    int err = sound_dequeue_cmd(&queues.cmd_res, &cmd);
    if (err) {
        sddf_printf("Failed to dequeue response while reset\n");
        fail();
        return;
    }

    if (cmd.status != SOUND_S_OK) {
        sddf_printf("Failed to %s: %s\n",
               sound_command_code_str(cmd.code),
               sound_status_code_str(cmd.status));
        fail();
        return;
    }

    switch (cmd.code) {
    case SOUND_CMD_START:
        stream_state = STATE_STARTED;
        update_playback();
        // Start benchmark
        microkit_notify(BENCH_START_CH);
        break;
    case SOUND_CMD_RELEASE:
        sddf_printf("Release success!\n");
        stream_state = STATE_RESET;
        break;
    default:
        sddf_printf("Unexpected command code %s\n", sound_command_code_str(cmd.code));
        fail();
        return;
    }
}

static void notified_started(void) {
    update_playback();
}

static void notified_draining(void) {
    // Dequeue any remaining PCM replies.
    sound_pcm_t pcm;
    while (sound_dequeue_pcm(&queues.pcm_res, &pcm) == 0);

    // Check if we got STOP command.
    sound_cmd_t cmd;
    if (sound_dequeue_cmd(&queues.cmd_res, &cmd) == 0) {
        if (cmd.code != SOUND_CMD_STOP) {
            sddf_printf("Expected command code %s but got %s\n",
                    sound_command_code_str(SOUND_CMD_STOP),
                    sound_command_code_str(cmd.code));
            fail();
            return;
        }
        if (cmd.status != SOUND_S_OK) {
            sddf_printf("Failed to %s: %s\n",
                    sound_command_code_str(SOUND_CMD_STOP),
                    sound_status_code_str(cmd.status));
            fail();
            return;
        }

        sddf_printf("Releasing stream\n");
        if (!send_simple_command(SOUND_CMD_RELEASE)) {
            fail();
            return;
        }

        stream_state = STATE_PREPARED;
        microkit_notify(VIRT_CH);
    }
}

static void notified_by_virt(void) {
    switch (stream_state) {
    case STATE_INIT:     notified_init();     break;
    case STATE_RESET:    notified_reset();    break;
    case STATE_TAKEN:    notified_taken();    break;
    case STATE_PREPARED: notified_prepared(); break;
    case STATE_STARTED:  notified_started();  break;
    case STATE_DRAINING: notified_draining(); break;
    case STATE_ERR:
        sddf_printf("Notified after fail\n");
        break;
    default:
        sddf_printf("Unknown state\n");
    }
}

void init(void) {
    assert(sound_cmd_req);
    assert(sound_cmd_res);
    assert(sound_pcm_req);
    assert(sound_pcm_res);
    assert(sound_data_region);
    assert(sound_shared_state);

    serial_cli_queue_init_sys(microkit_name, &rx_queue_handle, serial_rx_queue, serial_rx_data,
                              &tx_queue_handle, serial_tx_queue, serial_tx_data);
    serial_putchar_init(SERIAL_TX_CH, &tx_queue_handle);

    shared_state = (sound_shared_state_t *)sound_shared_state;

    sound_queues_init(&queues,
                      (void *)sound_cmd_req,
                      (void *)sound_cmd_res,
                      (void *)sound_pcm_req,
                      (void *)sound_pcm_res,
                      SOUND_CMD_QUEUE_SIZE,
                      SOUND_PCM_QUEUE_SIZE);

    sound_queues_init_buffers(&queues);

    queue_init(&free_buffers,
               sizeof(uintptr_t),
               &buffer_data,
               BUFFER_QUEUE_SIZE);

    for (uintptr_t i = 0; i < queues.pcm_req.size; i++) {
        uintptr_t offset = i * SOUND_PCM_BUFFER_SIZE;
        queue_enqueue(&free_buffers, &offset);
    }

    #ifdef CANTINA
    audio.format = SOUND_PCM_FMT_S16;
    audio.channels = 1;
    audio.frame_size = audio.channels * 2;
    audio.rate = SOUND_PCM_RATE_22050;
    audio.data = CantinaBand60_s16le;
    const unsigned int CantinaBand60_s16le_len = 529200;
    audio.len = CantinaBand60_s16le_len;
    #endif
    #ifdef CRAB
    audio.format = SOUND_PCM_FMT_S16;
    audio.channels = 2;
    audio.frame_size = audio.channels * 2;
    audio.rate = SOUND_PCM_RATE_44100;
    audio.data = crab_rave_pcm_s16le;
    const unsigned int crab_rave_pcm_s16le_len = 2116800;
    audio.len = crab_rave_pcm_s16le_len;
    #endif

    stream_state = STATE_INIT;
    playback_stream = -1;

    while (!ATOMIC_LOAD(&shared_state->ready, __ATOMIC_ACQUIRE));
    notified_by_virt();
}

void notified(microkit_channel ch) {
    switch (ch) {
    case VIRT_CH:
        notified_by_virt();
        break;
    default:
        sddf_printf("Unexpected channel, ch: 0x%lx\n", ch);
    }
}


